INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('3c9ebf0a-7b26-59b7-822d-52ac53301460','audio','Audio','Headphones, earbuds & speakers','Tuned for long listening sessions — from reference-grade over-ears to pocketable earbuds and speakers built for the balcony.','Audio is where Fusion began. Every product here is auditioned in our Bahraich listening room before it earns a shelf.','/images/cat-audio.jpg','oklch(0.62 0.13 55)',ARRAY['Headphones','Earbuds','Speakers'],'Shop premium headphones, wireless earbuds and Bluetooth speakers at Fusion Gadgets. Curated audio gear with active noise cancellation, hi-res certification and a 2-year warranty.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('28fc5d8e-3d24-57c9-9e1d-94501ef662fd','keyboards','Keyboards','Mechanical keyboards & keycaps','Gasket-mounted boards, hot-swap switches and keycaps you''ll want to photograph. Built for the kind of typing you look forward to.','A good keyboard is the most personal piece of tech you own. These are the ones our team actually uses every day.','/images/cat-keyboards.jpg','oklch(0.52 0.09 150)',ARRAY['Full-size','Compact','Keycaps','Switches'],'Buy mechanical keyboards online in India — gasket-mounted, hot-swappable, with PBT keycaps and tactile switches. Free shipping on keyboards above ₹4,990.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('f88324ee-8f09-59e3-bea6-a279e6cfbc0d','computing','Computing','Mice, monitors & desk hubs','The supporting cast: precise pointers, colour-accurate displays, and the aluminium stand that makes your laptop feel permanent.','Small upgrades that change how a desk feels. Mice that disappear in the hand, monitors that tell the truth about colour.','/images/cat-computing.jpg','oklch(0.45 0.06 230)',ARRAY['Mice','Monitors','Stands','Docks'],'Premium computer accessories — wireless mice, 4K monitors, Thunderbolt docks and aluminium laptop stands. Curated for designers and developers.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('960b4b8e-248a-5fb2-8c0b-fca70479f0a2','wearables','Wearables','Smartwatches & fitness trackers','Watches that respect your attention. Heart rate, sleep, and notifications — without the noise of a phone on your wrist.','Wearables should tell you less, better. These track what matters and stay out of the way the rest of the time.','/images/cat-wearables.jpg','oklch(0.58 0.16 340)',ARRAY['Smartwatches','Trackers','Bands'],'Shop smartwatches and fitness trackers with AMOLED displays, GPS and 7-day battery life. Available with EMI options and a 1-year warranty.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('c9607ede-6721-5607-a2bb-b2db9dc9bd73','cameras','Cameras','Cameras & lenses','Compact cameras for everyday moments and mirrorless bodies for the work that matters. Lenses chosen for character, not just sharpness.','Cameras that make you want to carry them. The best camera is the one in your bag — these earn the bag space.','/images/cat-cameras.jpg','oklch(0.45 0.04 250)',ARRAY['Compact','Mirrorless','Lenses'],'Buy cameras and prime lenses from Lumen — compact shooters, mirrorless bodies and fast primes with India warranty and 0% EMI.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('88f242d7-4bc2-58aa-9290-9b7087cf6e21','power','Power','Chargers & cables','GaN chargers that fold away, cables that don''t fray, and enough ports to charge the whole desk from one wall socket.','Unsexy, essential, and quietly the thing you''ll use most often. Buy the good ones once.','/images/cat-power.jpg','oklch(0.72 0.14 80)',ARRAY['Chargers','Cables','Hubs'],'GaN chargers, braided USB-C cables and multi-port desk chargers. Fast charging for laptops, phones and accessories.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('8e9d0f14-e598-570c-b3c6-867a3fdaa703','desks','Desks','Lamps, stands & risers','Lighting that flatters the work, walnut risers that lift the monitor to eye level, and the small objects that make a desk feel yours.','The desk is a workspace, not a warehouse. These earn their place by being useful and beautiful.','/images/cat-desks.jpg','oklch(0.55 0.08 60)',ARRAY['Lamps','Stands','Risers'],'Designer desk accessories — LED task lamps, walnut monitor risers and machined aluminium stands. Curated for focused, beautiful workspaces.') ON CONFLICT DO NOTHING;
INSERT INTO categories (id,slug,name,tagline,description,intro,image,accent,subcategories,seo_note) VALUES ('5839ea4e-2afa-58b4-ab21-b4ab5ad8d0f9','gaming-carry','Gaming & Carry','Controllers, headsets & bags','Controllers with real triggers, headsets you can wear for a raid, and bags that carry a laptop and a weekend.','Play hard, carry smart. The gear that survives commutes and tournaments alike.','/images/cat-carry.jpg','oklch(0.60 0.15 16)',ARRAY['Controllers','Headsets','Backpacks','Slings'],'Wireless controllers, gaming headsets, tech backpacks and sling bags. Built for gamers and travellers who want one bag for everything.') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('02c7a2e2-b081-598e-b8fa-699eb6c87350','HALOONEWIR','halo-one-wireless','Halo One Wireless Headphones','Over-ear · ANC · 40h battery','0a869769-95d7-5d83-9972-f735bf8a2a1b','3c9ebf0a-7b26-59b7-822d-52ac53301460','Headphones','Reference tuning, finally wireless.','The Halo One brings studio reference sound to a wireless over-ear. Adaptive ANC, 40-hour battery, and memory-foam earcups wrapped in protein leather.','We auditioned eleven flagship headphones before settling on the Halo One. What sold us wasn''t a spec — it was the midrange. Voices sit exactly where they should, neither pushed forward nor recessed. The ANC is class-leading for the price, and the 40-hour battery means you''ll forget the charger on a long trip and survive it. Includes a hard travel case and a 1.5m braided USB-C cable.',24990,29990,'INR','headphones','oklch(0.62 0.13 55)',42,TRUE,FALSE,ARRAY['Adaptive hybrid ANC tuned for Indian commute noise','LDAC + aptX HD for hi-res wireless','Multipoint pairing to two devices','Hard travel case included']::text[],ARRAY['Halo One headphones','Hard travel case','USB-C charging cable','3.5mm audio cable','Quick start guide']::text[],'[{"label":"Driver","value":"40mm dynamic"},{"label":"Frequency response","value":"8 Hz – 40 kHz"},{"label":"ANC","value":"Adaptive hybrid"},{"label":"Battery","value":"40h (ANC on)"},{"label":"Charging","value":"USB-C, 10 min = 5h"},{"label":"Weight","value":"252 g"},{"label":"Codecs","value":"LDAC, aptX HD, AAC, SBC"},{"label":"Warranty","value":"2 years"}]'::jsonb,4.7,318,'Ships within 24 hours. Free delivery across India in 2–4 days.','2-year manufacturer warranty. 7-day return window.','2024-08-12') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('67398651-bb73-58ec-924e-09c843d029c6','HALOSTUDIO','halo-studio-reference','Halo Studio Reference','Open-back · Wired · Studio','0a869769-95d7-5d83-9972-f735bf8a2a1b','3c9ebf0a-7b26-59b7-822d-52ac53301460','Headphones','Open-back, for the honest mix.','An open-back reference headphone for mixing, mastering, and the kind of listening where you want to hear everything — including the room.','Open-back headphones are a commitment: they leak sound and they let sound in. What you get in return is a soundstage that closed-backs simply cannot match. The Studio Reference is tuned flat, with a slight treble lift that reveals sibilance and harshness in a mix. Not for the commute. Built for the desk.',44500,NULL,'INR','headphones','oklch(0.45 0.04 250)',14,TRUE,FALSE,ARRAY['Flat reference tuning for mixing','Detachable OFC copper cable','Velour earpads, replaceable','Hand-assembled in Gothenburg']::text[],ARRAY['Halo Studio headphones','Detachable cable','1/4" adapter','Velour pad spare set']::text[],'[{"label":"Driver","value":"50mm bio-cellulose"},{"label":"Frequency response","value":"5 Hz – 45 kHz"},{"label":"Impedance","value":"80Ω"},{"label":"Cable","value":"2.5m detachable, 1/4\" adapter"},{"label":"Weight","value":"298 g"},{"label":"Type","value":"Open-back, over-ear"}]'::jsonb,4.9,87,'Ships within 24 hours. Free insured delivery in 2–4 days.','2-year manufacturer warranty.','2024-06-20') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('6df1bab1-f722-5f9d-9048-96594ac9ecad','ECHOPROANC','echo-pro-anc-earbuds','Echo Pro ANC Earbuds','In-ear · ANC · 8h + 24h case','1efa6465-13a1-54c0-999b-8b3231987368','3c9ebf0a-7b26-59b7-822d-52ac53301460','Earbuds','Pocketable quiet.','True wireless earbuds with adaptive ANC, a snug fit that survives a run, and a case small enough to forget in a pocket.','The Echo Pro is the earbud we recommend to people who hate earbuds. The nozzle is short and angled to sit flush, the ANC is genuinely useful on a flight, and the case charges wirelessly. Eight hours per charge means you''ll rarely need the case during the day.',14990,NULL,'INR','earbuds','oklch(0.60 0.13 55)',86,TRUE,FALSE,ARRAY['Adaptive ANC with transparency mode','Wireless charging case','IPX5 sweat resistance','Multipoint pairing']::text[],ARRAY['Echo Pro earbuds','Charging case','USB-C cable','4 silicone tip sizes','Warranty card']::text[],'[{"label":"Driver","value":"11mm dynamic"},{"label":"ANC","value":"Adaptive, -42 dB"},{"label":"Battery","value":"8h buds / 24h case"},{"label":"Charging","value":"USB-C + Qi wireless"},{"label":"Water resistance","value":"IPX5"},{"label":"Codecs","value":"aptX, AAC, SBC"}]'::jsonb,4.5,542,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty. 7-day returns.','2024-09-05') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('14d0aada-765a-5058-bfc8-b855372c3424','ECHOLITEEA','echo-lite-earbuds','Echo Lite Earbuds','In-ear · 6h + 18h case','1efa6465-13a1-54c0-999b-8b3231987368','3c9ebf0a-7b26-59b7-822d-52ac53301460','Earbuds','The everyday pair.','Reliable wireless earbuds without the flagship tax. Clear sound, a comfortable fit, and a case that fits any pocket.','',6990,NULL,'INR','earbuds','oklch(0.72 0.14 80)',7,TRUE,FALSE,ARRAY['Balanced tuning','USB-C fast charge','Touch controls','Low-latency game mode']::text[],ARRAY['Echo Lite earbuds','Charging case','USB-C cable','3 silicone tip sizes']::text[],'[{"label":"Driver","value":"10mm dynamic"},{"label":"Battery","value":"6h buds / 18h case"},{"label":"Charging","value":"USB-C"},{"label":"Water resistance","value":"IPX4"}]'::jsonb,4.3,921,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty.','2024-07-15') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('7a78b795-2fa1-520c-a8ba-9b6ce14a9d22','PEBBLEMINI','pebble-mini-speaker','Pebble Mini Bluetooth Speaker','Portable · 12h · IP67','377055a7-a2f6-5519-bdb7-66f995d2f79e','3c9ebf0a-7b26-59b7-822d-52ac53301460','Speakers','Pocket-sized, balcony-loud.','A rugged, waterproof Bluetooth speaker that punches well above its size. Strap it to a bag, drop it in a pool, take it camping.','',8490,NULL,'INR','speaker','oklch(0.60 0.13 55)',53,TRUE,FALSE,ARRAY['IP67 dust and waterproof','Stereo pairing of two units','Built-in strap','USB-C charging']::text[],ARRAY['Pebble Mini speaker','USB-C cable','Carry strap']::text[],'[{"label":"Output","value":"10W RMS"},{"label":"Battery","value":"12h at 50% volume"},{"label":"Water resistance","value":"IP67"},{"label":"Bluetooth","value":"5.3, 30m range"},{"label":"Weight","value":"310 g"}]'::jsonb,4.4,263,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty.','2024-08-01') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('dd1882ec-1f6c-5678-bfeb-f54292942c70','PEBBLEFIEL','pebble-field-speaker','Pebble Field Speaker','Portable · 20h · Stereo pair','377055a7-a2f6-5519-bdb7-66f995d2f79e','3c9ebf0a-7b26-59b7-822d-52ac53301460','Speakers','Built for the long evening.','A larger portable speaker with a passive radiator for real bass, 20-hour battery, and the ability to pair two for stereo.','',12990,NULL,'INR','speaker','oklch(0.55 0.08 60)',28,TRUE,FALSE,ARRAY['30W with passive radiator','Stereo pair two units','20-hour battery','USB-C power bank mode']::text[],ARRAY['Pebble Field speaker','USB-C cable','Carry strap']::text[],'[{"label":"Output","value":"30W RMS"},{"label":"Battery","value":"20h at 50% volume"},{"label":"Water resistance","value":"IP67"},{"label":"Bluetooth","value":"5.3"},{"label":"Weight","value":"740 g"}]'::jsonb,4.6,141,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty.','2024-07-22') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('74c59b3f-115c-5503-9f38-c4184e173ba6','RESONANCEB','resonance-bookshelf','Resonance Bookshelf Speaker (Pair)','Passive · Bookshelf · Walnut','87a13082-4db1-5166-8378-6a334a641b02','3c9ebf0a-7b26-59b7-822d-52ac53301460','Speakers','Honest sound, real wood.','A pair of passive bookshelf speakers in solid walnut. Pair with the Spark amp or any receiver for a proper living-room system.','',38990,NULL,'INR','speaker','oklch(0.45 0.06 230)',0,TRUE,FALSE,ARRAY['Solid walnut cabinets','Silk dome tweeter','Front-firing bass port','Sold as a matched pair']::text[],ARRAY['2 bookshelf speakers','Grilles','Foam isolation pads']::text[],'[{"label":"Type","value":"2-way passive"},{"label":"Drivers","value":"5\" woofer + 1\" silk tweeter"},{"label":"Impedance","value":"6Ω"},{"label":"Cabinet","value":"Solid walnut, hand-finished"},{"label":"Weight","value":"6.8 kg each"}]'::jsonb,4.8,34,'Made to order. Ships in 2–3 weeks.','5-year warranty on cabinets, 2-year on drivers.','2024-05-10') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('80855748-76ef-5dcd-b5f4-dde58a306f07','TYPE75MECH','type-75-mechanical','Type 75 Mechanical Keyboard','75% · Gasket mount · Hot-swap','f9876416-bf56-5081-bc36-de07bee2136a','28fc5d8e-3d24-57c9-9e1d-94501ef662fd','Compact','The board that ended our search.','A 75% gasket-mounted mechanical keyboard with hot-swap switches, PBT keycaps, and a knob you''ll actually use. Wireless or wired.','The Type 75 is the keyboard half our team uses daily. The gasket mount gives a soft, cushioned bottom-out that''s addictive. Hot-swap sockets mean you can change switches without soldering. The knob controls volume by default — remap it to anything. Connects over USB-C, Bluetooth, or 2.4GHz.',18990,NULL,'INR','keyboard','oklch(0.52 0.09 150)',31,TRUE,FALSE,ARRAY['Gasket-mounted for soft typing feel','Hot-swap switches — change without soldering','Tri-mode connectivity','Aluminium plate, PBT keycaps']::text[],ARRAY['Type 75 keyboard','USB-C cable','Switch puller','Keycap puller','2 spare switches','Carry sleeve']::text[],'[{"label":"Layout","value":"75%, 84 keys"},{"label":"Mount","value":"Gasket-mounted"},{"label":"Switches","value":"Hot-swap, pre-lubed tactile"},{"label":"Keycaps","value":"PBT double-shot, Cherry profile"},{"label":"Connectivity","value":"USB-C / Bluetooth / 2.4GHz"},{"label":"Battery","value":"4000mAh, ~4 weeks"},{"label":"RGB","value":"South-facing per-key"}]'::jsonb,4.8,204,'Ships within 24 hours. Free delivery in 2–4 days.','2-year warranty.','2024-08-30') ON CONFLICT DO NOTHING;
INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('1b3aafcd-6374-5540-b56f-349137b32a68','TYPE65COMP','type-65-compact','Type 65 Compact Keyboard','65% · Hot-swap · Wireless','f9876416-bf56-5081-bc36-de07bee2136a','28fc5d8e-3d24-57c9-9e1d-94501ef662fd','Compact','Small board, full feel.','A 65% keyboard that gives up the function row but keeps the arrow keys. Same gasket mount, same hot-swap, smaller footprint.','',14500,NULL,'INR','keyboard','oklch(0.60 0.13 55)',5,TRUE,FALSE,ARRAY['Compact 65% with arrows','Hot-swap switches','Bluetooth + USB-C','PBT keycaps']::text[],ARRAY['Type 65 keyboard','USB-C cable','Keycap puller']::text[],'[{"label":"Layout","value":"65%, 67 keys"},{"label":"Mount","value":"Gasket-mounted"},{"label":"Switches","value":"Hot-swap, pre-lubed linear"},{"label":"Keycaps","value":"PBT dye-sublimated"},{"label":"Connectivity","value":"USB-C / Bluetooth"},{"label":"Battery","value":"3000mAh"}]'::jsonb,4.6,118,'Ships within 24 hours. Free delivery in 2–4 days.','2-year warranty.','2024-07-01') ON CONFLICT DO NOTHING;
