INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('4f7dc738-ac58-57e7-8f0c-6f1ddb15947e','PULSE2SMAR','pulse-2-smartwatch','Pulse 2 Smartwatch','AMOLED · GPS · 7-day','4210d67f-9a73-52cc-90ae-c03b418e11bf','960b4b8e-248a-5fb2-8c0b-fca70479f0a2','Smartwatches','Tells you less, better.','A smartwatch with a bright AMOLED display, built-in GPS, and a seven-day battery. Notifications without the noise.','Pulse 2 is a watch first, smartwatch second. The display is bright enough to read in direct sun, the GPS locks in seconds, and the battery genuinely lasts a week. It filters notifications so you see what matters and skips the rest. No app store full of junk — just the things a watch should do, done well.',21990,24990,'INR','watch','oklch(0.58 0.16 340)',38,TRUE,FALSE,ARRAY['Dual-band GPS for accurate runs','1000-nit always-on AMOLED','7-day battery','Titanium case, 43mm']::text[],ARRAY['Pulse 2 watch','Silicone band','Magnetic charger','Quick start guide']::text[],'[{"label":"Display","value":"1.4\" AMOLED, 1000 nits"},{"label":"Battery","value":"7 days typical, 14 days low-power"},{"label":"GPS","value":"Dual-band, multi-GNSS"},{"label":"Water resistance","value":"5 ATM"},{"label":"Sensors","value":"HR, SpO2, temp, accelerometer, compass"},{"label":"Case","value":"43mm, titanium"}]'::jsonb,4.6,287,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty.','2024-09-20') ON CONFLICT DO NOTHING;
