INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('9e615a95-a256-5369-88e3-2ce349f5668f','HALOONGRAP','halo-one-wireless-graphite','Halo One Wireless Headphones — Graphite','Over-ear · ANC · 40h battery','0a869769-95d7-5d83-9972-f735bf8a2a1b','3c9ebf0a-7b26-59b7-822d-52ac53301460','Headphones','Reference tuning, finally wireless.','The Halo One brings studio reference sound to a wireless over-ear. Adaptive ANC, 40-hour battery, and memory-foam earcups wrapped in protein leather.','We auditioned eleven flagship headphones before settling on the Halo One. What sold us wasn''t a spec — it was the midrange. Voices sit exactly where they should, neither pushed forward nor recessed. The ANC is class-leading for the price, and the 40-hour battery means you''ll forget the charger on a long trip and survive it. Includes a hard travel case and a 1.5m braided USB-C cable.',24990,29990,'INR','headphones','oklch(0.62 0.13 55)',10,TRUE,FALSE,'{{}}'::text[],'{{}}'::text[],'[]'::jsonb,4.7,0,'Ships within 24 hours. Free delivery across India in 2–4 days.','2-year manufacturer warranty. 7-day return window.','2024-08-12') ON CONFLICT DO NOTHING;
