INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('edad170d-ded6-5df3-923d-ccb322f17dce','PULSE2GRAP','pulse-2-smartwatch-graphite','Pulse 2 Smartwatch — Graphite','AMOLED · GPS · 7-day','4210d67f-9a73-52cc-90ae-c03b418e11bf','960b4b8e-248a-5fb2-8c0b-fca70479f0a2','Smartwatches','Tells you less, better.','A smartwatch with a bright AMOLED display, built-in GPS, and a seven-day battery. Notifications without the noise.','Pulse 2 is a watch first, smartwatch second. The display is bright enough to read in direct sun, the GPS locks in seconds, and the battery genuinely lasts a week. It filters notifications so you see what matters and skips the rest. No app store full of junk — just the things a watch should do, done well.',21990,24990,'INR','watch','oklch(0.58 0.16 340)',10,TRUE,FALSE,'{{}}'::text[],'{{}}'::text[],'[]'::jsonb,4.6,0,'Ships within 24 hours. Free delivery in 2–4 days.','1-year warranty.','2024-09-20') ON CONFLICT DO NOTHING;
