INSERT INTO products (id,sku,slug,name,subtitle,brand_id,category_id,subcategory,tagline,description,story,price,compare_at_price,currency,visual_key,accent,stock,is_active,is_preorder,highlights,includes,specs,rating,review_count,shipping,warranty,added_at) VALUES ('c9531970-18c0-5ce4-aa95-eef4769d860d','LUMENXSILV','lumen-x100-compact-silver','Lumen X100 Compact Camera — Silver','Compact · 26MP · f/2 lens','66a4541c-db58-5b81-b9fc-457c52eb559f','c9607ede-6721-5607-a2bb-b2db9dc9bd73','Compact','The camera you''ll actually carry.','A fixed-lens compact camera with a large sensor, a fast prime lens, and dials for everything. The camera that lives in your bag.','The X100 is the camera that ruined point-and-shoots for us. A big APS-C sensor behind a sharp f/2 prime, with physical dials for shutter, aperture, and exposure comp. Leaf shutter means silent shooting and flash sync at any speed. Hybrid optical/electronic viewfinder. This is the camera you take everywhere because it fits everywhere.',74990,NULL,'INR','camera','oklch(0.45 0.04 250)',10,TRUE,FALSE,'{{}}'::text[],'{{}}'::text[],'[]'::jsonb,4.9,0,'Ships within 24 hours. Free insured delivery in 3–5 days.','2-year India warranty.','2024-08-05') ON CONFLICT DO NOTHING;
